<?php require __DIR__.'/config/bootstrap.php';verify_csrf();$id=(int)($_POST['post_id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$comment=trim($_POST['comment']??'');if(!$id||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$comment)exit('Invalid input');$st=db()->prepare("INSERT INTO comments(post_id,name,email,comment,status,ip_address) VALUES(?,?,?,?, 'pending', ?)");$st->execute([$id,$name,$email,$comment,$_SERVER['REMOTE_ADDR']??'']);$p=db()->prepare("SELECT slug FROM posts WHERE id=?");$p->execute([$id]);$slug=$p->fetchColumn();flash('success','Comment submitted for moderation.');redirect('post.php?slug='.urlencode($slug));